import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import javax.inject.Named;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.*;

@PluginDescriptor(
		name = "Remastered Xp Globes",
		description = "Improves xp globes and adds level up notifications like 2011",
		tags = {"2011", "xp", "globes", "rs2", "level", "skill", "experience"}
)
@PluginDependency(XpTrackerPlugin.class)
public class RemasteredXpGlobes extends Plugin {

	private static final long XP_SYNC_PENDING_MS = 1500;
	private static final int STATS_TAB_CHILD_COUNT = 25;

	private XpGlobe[] globeCache = new XpGlobe[Skill.values().length];
	private int[] previousLevels = new int[Skill.values().length];
	private boolean[] skillInitialized = new boolean[Skill.values().length];
	private int initializedSkillCount = 0;
	private boolean levelsInitialized = false;
	private long xpDropSyncPendingTime = 0;

	@Getter
	private final List<XpGlobe> xpGlobes = new ArrayList<>();

	@Getter
	private final List<LevelUpGlobe> levelUpQueue = new ArrayList<>();

	@Getter
	private LevelUpGlobe currentLevelUp;

	@Inject
	private Client client;

	@Inject
	private RemasteredXpGlobesConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private XpGlobesOverlay overlay;

	@Inject
	private LevelUpGlobesOverlay levelUpOverlay;

	@Inject
	private QuestData questData;

	@Inject
	private SkillData skillData;

	@Inject
	@Named("developerMode")
	boolean developerMode;

	@Provides
	RemasteredXpGlobesConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(RemasteredXpGlobesConfig.class);
	}

	@Override
	protected void startUp() {
		overlayManager.add(overlay);
		overlayManager.add(levelUpOverlay);
		levelsInitialized = false;
		questData.load();
		skillData.load();

		handeSkillPulseGlowState();
		if (client.getGameState() == GameState.LOGGED_IN) {
			initializeLevelTrackingFromClient();
			overlay.initPreviousXp();
			xpDropSyncPendingTime = System.currentTimeMillis();
		}
	}

	@Override
	public void shutDown() {
		resetGlobeState();
		overlay.clearCache();
		overlay.clearXpDrops();
		levelUpOverlay.clearCache();
		handeSkillPulseGlowState();
		overlayManager.remove(overlay);
		overlayManager.remove(levelUpOverlay);
		globeCache = new XpGlobe[Skill.values().length];
		previousLevels = new int[Skill.values().length];
		skillInitialized = new boolean[Skill.values().length];
		initializedSkillCount = 0;
		levelsInitialized = false;
		xpDropSyncPendingTime = 0;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged) {
		if (Objects.equals(configChanged.getKey(), "skillIconMode")) {
			handeSkillPulseGlowState();
		}
		if (Objects.equals(configChanged.getKey(), "customSpritesPath") || Objects.equals(configChanged.getKey(), "globeStyle")) {
			overlay.clearCache();
			levelUpOverlay.clearCache();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged) {
		Skill skill = statChanged.getSkill();
		int currentXp = statChanged.getXp();
		int currentLevel = statChanged.getLevel();
		int skillIdx = skill.ordinal();
		Instant now = Instant.now();

		overlay.onStatChanged(skill, currentXp);

		if (!levelsInitialized) {
			if (!skillInitialized[skillIdx]) {
				skillInitialized[skillIdx] = true;
				initializedSkillCount++;
			}

			previousLevels[skillIdx] = currentLevel;

			if (initializedSkillCount == Skill.values().length) {
				levelsInitialized = true;
			}

			return;
		}

		int previousLevel = previousLevels[skillIdx];

		if (currentLevel > previousLevel && !config.disableLevelUpPopups()) {
			Map<Skill, Integer> playerLevels = new HashMap<>();
			for (Skill s : Skill.values()) {
				playerLevels.put(s, client.getRealSkillLevel(s));
			}
			playerLevels.put(skill, currentLevel);

			QuestUnlockResult questUnlockResult = questData.checkQuestUnlocks(skill, currentLevel, previousLevel, playerLevels);

			LevelUpGlobe levelUp = new LevelUpGlobe(
					skill,
					currentLevel,
					now,
					questUnlockResult,
					skillData,
					previousLevel,
					config.maxMilestones(),
					config.questRequirementMode(),
					config.skillUnlockRequirementMode(),
					config.showSkillLevelUps(),
					playerLevels
			);
			levelUpQueue.add(levelUp);
			processLevelUpQueue();
		}

		if (currentLevelUp != null && !config.disableLevelUpPopups()) {
			previousLevels[skillIdx] = currentLevel;
			return;
		}

		XpGlobe cachedGlobe = globeCache[skillIdx];
		if (cachedGlobe != null && cachedGlobe.getCurrentXp() >= currentXp) {
			previousLevels[skillIdx] = currentLevel;
			return;
		}

		int displayLevel = currentLevel;
		if (displayLevel >= Experience.MAX_REAL_LEVEL) {
			if (config.hideMaxed()) {
				previousLevels[skillIdx] = currentLevel;
				return;
			}
			if (config.showVirtualLevel()) {
				displayLevel = Experience.getLevelForXp(currentXp);
			}
		}

		if (cachedGlobe == null) {
			globeCache[skillIdx] = new XpGlobe(skill, currentXp, displayLevel, now);
			previousLevels[skillIdx] = currentLevel;
			cachedGlobe = globeCache[skillIdx];
		}

		cachedGlobe.setSkill(skill);
		cachedGlobe.setCurrentXp(currentXp);
		cachedGlobe.setCurrentLevel(displayLevel);
		cachedGlobe.setTime(now);
		addXpGlobe(cachedGlobe);
		previousLevels[skillIdx] = currentLevel;
	}

	private void processLevelUpQueue() {
		if (currentLevelUp == null && !levelUpQueue.isEmpty()) {
			currentLevelUp = levelUpQueue.remove(0);
		}
	}

	private void addXpGlobe(XpGlobe xpGlobe) {
		XpGlobe existingGlobe = xpGlobes.stream()
				.filter(globe -> globe.getSkill() == xpGlobe.getSkill())
				.findFirst()
				.orElse(null);

		if (existingGlobe != null) {
			existingGlobe.setCurrentXp(xpGlobe.getCurrentXp());
			existingGlobe.setCurrentLevel(xpGlobe.getCurrentLevel());
			existingGlobe.setTime(xpGlobe.getTime());
		} else {
			xpGlobes.add(xpGlobe);
			if (xpGlobes.size() > config.maximumGlobes()) {
				xpGlobes.stream().min(Comparator.comparing(XpGlobe::getTime)).ifPresent(xpGlobes::remove);
			}
		}
	}

	@Schedule(period = 1, unit = ChronoUnit.SECONDS)
	public void removeExpiredXpGlobes() {
		if (xpDropSyncPendingTime > 0 && System.currentTimeMillis() - xpDropSyncPendingTime >= XP_SYNC_PENDING_MS) {
			overlay.syncPreviousXpFromClient();
			xpDropSyncPendingTime = 0;
		}

		if (!xpGlobes.isEmpty()) {
			Instant expireTime = Instant.now().minusSeconds(config.xpOrbDuration());
			xpGlobes.removeIf(globe -> globe.getTime().isBefore(expireTime));
		}

		if (currentLevelUp != null) {
			long levelUpDurationSec = getLevelUpDurationSeconds(currentLevelUp);
			Instant expireTime = Instant.now().minusSeconds(levelUpDurationSec);
			if (currentLevelUp.getTime().isBefore(expireTime)) {
				currentLevelUp = null;
				processLevelUpQueue();
			}
		}
	}

	private long getLevelUpDurationSeconds(LevelUpGlobe levelUp) {
		int maxMilestones = 0;
		if (config.showMilestones() && levelUp.getMilestones() != null) {
			maxMilestones = Math.min(config.maxMilestones(), levelUp.getMilestones().size());
		}
		return (3300 + maxMilestones * 3000L + 2000) / 1000;
	}

	private void resetGlobeState() {
		xpGlobes.clear();
		globeCache = new XpGlobe[Skill.values().length];
		levelUpQueue.clear();
		currentLevelUp = null;
		Arrays.fill(skillInitialized, false);
		Arrays.fill(previousLevels, 0);
		initializedSkillCount = 0;
		levelsInitialized = false;
	}

	private void initializeLevelTrackingFromClient() {
		for (Skill skill : Skill.values()) {
			int idx = skill.ordinal();
			previousLevels[idx] = client.getRealSkillLevel(skill);
			skillInitialized[idx] = true;
		}
		initializedSkillCount = Skill.values().length;
		levelsInitialized = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		switch (event.getGameState()) {
			case HOPPING:
			case LOGGING_IN:
				resetGlobeState();
				overlay.clearXpDrops();
				xpDropSyncPendingTime = 0;
				break;
			case LOGGED_IN:
				overlay.initPreviousXp();
				xpDropSyncPendingTime = System.currentTimeMillis();
				break;
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (!developerMode) return;

		String command = event.getCommand();
		String[] args = event.getArguments();

		try {
			if ("orb".equals(command)) {
				Skill skill;
				if (args != null && args.length == 1) {
					skill = Skill.valueOf(args[0].toUpperCase());
				} else {
					Skill[] skills = Skill.values();
					skill = skills[(int) (Math.random() * skills.length)];
				}
				int idx = skill.ordinal();
				int xp = client.getSkillExperience(skill);
				int level = client.getRealSkillLevel(skill);

				XpGlobe globe = new XpGlobe(skill, xp, level, Instant.now());
				globeCache[idx] = globe;
				addXpGlobe(globe);

			} else if ("orball".equals(command)) {
				for (Skill skill : Skill.values()) {
					int idx = skill.ordinal();
					int xp = client.getSkillExperience(skill);
					int level = client.getRealSkillLevel(skill);

					XpGlobe globe = new XpGlobe(skill, xp, level, Instant.now());
					globeCache[idx] = globe;
					addXpGlobe(globe);
				}

			} else if ("olevel".equals(command)) {
				if (args == null || args.length < 2) return;

				Skill skill = Skill.valueOf(args[0].toUpperCase());
				int newLevel = Integer.parseInt(args[1]);

				Map<Skill, Integer> playerLevels = new EnumMap<>(Skill.class);
				for (Skill s : Skill.values()) {
					playerLevels.put(s, client.getRealSkillLevel(s));
				}
				int previousLevel = playerLevels.getOrDefault(skill, 0);
				playerLevels.put(skill, newLevel);

				QuestUnlockResult questUnlockResult =
						questData.checkQuestUnlocks(skill, newLevel, previousLevel, playerLevels);

				LevelUpGlobe levelUp = new LevelUpGlobe(skill, newLevel, Instant.now(), questUnlockResult,
						skillData,
						previousLevel,
						config.maxMilestones(),
						config.questRequirementMode(),
						config.skillUnlockRequirementMode(),
						config.showSkillLevelUps(),
						playerLevels
				);

				levelUpQueue.add(levelUp);
				processLevelUpQueue();
			}
		} catch (IllegalArgumentException ignored) {
			// ignore invalid skill or number format
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() == InterfaceID.STATS) {
			handeSkillPulseGlowState();
		}
	}

	public void handeSkillPulseGlowState() {
		boolean hideGlow = config.skillIconMode() == SkillIconMode.ALPHA_PULSE;

		for (int i = 1; i <= STATS_TAB_CHILD_COUNT; i++) {
			Widget parent = client.getWidget(InterfaceID.STATS, i);

			if (parent == null) {
				continue;
			}

			Widget glowIcon = parent.getChild(2);

			if (glowIcon != null) {
				glowIcon.setHidden(hideGlow);
			}
		}
	}
}

package io.mark.globes;

import net.runelite.client.ui.FontManager;

import java.awt.Font;

public enum OverlayFontType {
	RUNESCAPE("RuneScape", FontManager.getRunescapeFont()),
	RUNESCAPE_SMALL("RuneScape Small", FontManager.getRunescapeSmallFont()),
	RUNESCAPE_BOLD("RuneScape Bold", FontManager.getRunescapeBoldFont()),
	DEFAULT("Default", FontManager.getDefaultFont()),
	VERDANA_BOLD("Verdana", new Font("Verdana", Font.BOLD, 11));

	private final String displayName;
	private final Font font;

	OverlayFontType(String displayName, Font font) {
		this.displayName = displayName;
		this.font = font;
	}

	public Font getFont() {
		return font;
	}

	@Override
	public String toString() {
		return displayName;
	}
}

package io.mark.globes.util;

import net.runelite.client.util.ImageUtil;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.function.Supplier;

public class ImageCache {
	private static final String MODERN_PREFIX = "globes_modern/";

	private final Class<?> resourceClass;
	private final Supplier<String> resourcePathSupplier;
	private final int baseWidth;
	private final int baseHeight;
	private final Supplier<String> customBasePath;

	private BufferedImage baseImage;
	private BufferedImage[] baseImages;

	private BufferedImage cachedScaledImage;
	private BufferedImage[] cachedScaledImages;
	private int cachedScale = -1;

	public ImageCache(Class<?> resourceClass, String resourcePath, int baseWidth, int baseHeight) {
		this(resourceClass, () -> resourcePath, baseWidth, baseHeight, null);
	}

	public ImageCache(Class<?> resourceClass, String resourcePath, int baseWidth, int baseHeight, Supplier<String> customBasePath) {
		this(resourceClass, () -> resourcePath, baseWidth, baseHeight, customBasePath);
	}

	public ImageCache(Class<?> resourceClass, Supplier<String> resourcePathSupplier, int baseWidth, int baseHeight, Supplier<String> customBasePath) {
		this.resourceClass = resourceClass;
		this.resourcePathSupplier = resourcePathSupplier;
		this.baseWidth = baseWidth;
		this.baseHeight = baseHeight;
		this.customBasePath = customBasePath != null ? customBasePath : () -> "";
	}

	public ImageCache(Class<?> resourceClass, String resourcePathPrefix, int count, int baseWidth, int baseHeight) {
		this(resourceClass, resourcePathPrefix, count, baseWidth, baseHeight, null);
	}

	public ImageCache(Class<?> resourceClass, String resourcePathPrefix, int count, int baseWidth, int baseHeight, Supplier<String> customBasePath) {
		this(resourceClass, () -> resourcePathPrefix, count, baseWidth, baseHeight, customBasePath);
	}

	public ImageCache(Class<?> resourceClass, Supplier<String> resourcePathPrefixSupplier, int count, int baseWidth, int baseHeight, Supplier<String> customBasePath) {
		this.resourceClass = resourceClass;
		this.resourcePathSupplier = resourcePathPrefixSupplier;
		this.baseWidth = baseWidth;
		this.baseHeight = baseHeight;
		this.customBasePath = customBasePath != null ? customBasePath : () -> "";
		this.baseImages = new BufferedImage[count];
		this.cachedScaledImages = new BufferedImage[count];
	}

	public static BufferedImage loadImageFromFile(File file, int expectedWidth, int expectedHeight) {
		if (file == null || !file.isFile()) {
			return null;
		}
		try {
			BufferedImage img = ImageIO.read(file);
			if (img != null && img.getWidth() == expectedWidth && img.getHeight() == expectedHeight) {
				return img;
			}
		} catch (Throwable ignored) {
		}
		return null;
	}

	private BufferedImage safeLoadResource(String path) {
		try {
			return ImageUtil.loadImageResource(resourceClass, path);
		} catch (Throwable ignored) {
			return null;
		}
	}

	private void loadBaseImage() {
		if (baseImage != null) {
			return;
		}
		String resourcePath = resourcePathSupplier.get();
		if (resourcePath == null) resourcePath = "";
		try {
			String path = customBasePath.get();
			if (path != null && !path.trim().isEmpty()) {
				File file = new File(path.trim(), resourcePath.replace('/', File.separatorChar));
				BufferedImage custom = loadImageFromFile(file, baseWidth, baseHeight);
				if (custom != null) {
					baseImage = custom;
					return;
				}
			}
		} catch (Throwable ignored) {
		}
		baseImage = safeLoadResource(resourcePath);
		if (baseImage == null && resourcePath.startsWith(MODERN_PREFIX)) {
			baseImage = safeLoadResource(resourcePath.substring(MODERN_PREFIX.length()));
		}
	}

	private void loadBaseImages(int count) {
		String prefix = resourcePathSupplier.get();
		if (prefix == null) prefix = "";
		for (int i = 0; i < count; i++) {
			if (baseImages[i] != null) {
				continue;
			}
			String relativePath = prefix + i + ".png";
			try {
				String path = customBasePath.get();
				if (path != null && !path.trim().isEmpty()) {
					File file = new File(path.trim(), relativePath.replace('/', File.separatorChar));
					BufferedImage custom = loadImageFromFile(file, baseWidth, baseHeight);
					if (custom != null) {
						baseImages[i] = custom;
						continue;
					}
				}
			} catch (Throwable ignored) {
			}
			baseImages[i] = safeLoadResource(relativePath);
			if (baseImages[i] == null && prefix.startsWith(MODERN_PREFIX)) {
				baseImages[i] = safeLoadResource(prefix.substring(MODERN_PREFIX.length()) + i + ".png");
			}
		}
	}

	public BufferedImage getScaledImage(int scale) {
		if (baseImage == null) {
			try {
				loadBaseImage();
			} catch (Throwable ignored) {
				String p = resourcePathSupplier.get();
				baseImage = safeLoadResource(p != null ? p : "");
				if (baseImage == null && p != null && p.startsWith(MODERN_PREFIX)) {
					baseImage = safeLoadResource(p.substring(MODERN_PREFIX.length()));
				}
			}
		}
		if (baseImage == null) {
			return null;
		}

		if (scale == cachedScale && cachedScaledImage != null) {
			return cachedScaledImage;
		}

		double scaleFactor = scale / 100.0;
		int scaledWidth = (int) (baseWidth * scaleFactor);
		int scaledHeight = (int) (baseHeight * scaleFactor);

		cachedScaledImage = ImageUtil.resizeImage(baseImage, scaledWidth, scaledHeight, true);
		cachedScale = scale;

		return cachedScaledImage;
	}

	public BufferedImage getScaledImage(int index, int scale) {
		if (baseImages == null || index < 0 || index >= baseImages.length) {
			return null;
		}
		if (baseImages[index] == null) {
			try {
				loadBaseImages(baseImages.length);
			} catch (Throwable ignored) {
				String prefix = resourcePathSupplier.get();
				if (prefix == null) prefix = "";
				for (int i = 0; i < baseImages.length; i++) {
					if (baseImages[i] == null) {
						baseImages[i] = safeLoadResource(prefix + i + ".png");
						if (baseImages[i] == null && prefix.startsWith(MODERN_PREFIX)) {
							baseImages[i] = safeLoadResource(prefix.substring(MODERN_PREFIX.length()) + i + ".png");
						}
					}
				}
			}
		}
		if (baseImages[index] == null) {
			return null;
		}

		if (cachedScaledImages == null) {
			cachedScaledImages = new BufferedImage[baseImages.length];
		}

		if (scale == cachedScale && cachedScaledImages[index] != null) {
			return cachedScaledImages[index];
		}

		if (scale != cachedScale) {
			double scaleFactor = scale / 100.0;

			int scaledWidth = (int) (baseWidth * scaleFactor);
			int scaledHeight = (int) (baseHeight * scaleFactor);

			for (int i = 0; i < baseImages.length; i++) {
				BufferedImage img = baseImages[i];
				if (img == null) {
					continue;
				}

				cachedScaledImages[i] = ImageUtil.resizeImage(img, scaledWidth, scaledHeight, true);
			}

			cachedScale = scale;
		}

		return cachedScaledImages[index];
	}

	public BufferedImage[] getAllScaledImages(int scale) {
		if (baseImages == null) {
			return null;
		}

		getScaledImage(0, scale);
		return cachedScaledImages;
	}

	public void clearCache() {
		baseImage = null;
		if (baseImages != null) {
			for (int i = 0; i < baseImages.length; i++) {
				baseImages[i] = null;
			}
		}
		cachedScaledImage = null;
		if (baseImages != null) {
			cachedScaledImages = new BufferedImage[baseImages.length];
		} else {
			cachedScaledImages = null;
		}
		cachedScale = -1;
	}
}

package io.mark.globes;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Configuration interface for the HD Minimap plugin
 */
@ConfigGroup(RemasteredXpGlobesConfig.CONFIG_GROUP)
public interface RemasteredXpGlobesConfig extends Config {

	String CONFIG_GROUP = "remasteredxpglobes";

	@ConfigSection(
			name = "Global",
			description = "General settings.",
			position = 0
	)
	String globalSection = "global";

	@ConfigSection(
			name = "Progress orbs",
			description = "XP progress orb settings.",
			closedByDefault = true,
			position = 1
	)
	String progressOrbsSection = "progressOrbs";

	@ConfigSection(
			name = "Level up orbs",
			description = "Level-up orb settings.",
			closedByDefault = true,
			position = 2
	)
	String levelUpOrbsSection = "levelUpOrbs";

	@ConfigSection(
			name = "Progress Tooltips",
			description = "Progress Orb Tooltips.",
			closedByDefault = true,
			position = 3
	)
	String xpTooltipSection = "xpOrbsTooltips";

	@ConfigSection(
			name = "XP drop popups",
			description = "Floating XP popup that appears from center of screen.",
			closedByDefault = true,
			position = 4
	)
	String xpDropsSection = "xpDrops";

	@ConfigItem(
			keyName = "globeStyle",
			name = "Style",
			description = "Classic: globes dir. Modern: globes_modern dir. Custom: folder path below.",
			section = globalSection,
			position = 0
	)
	default GlobeStyle globeStyle()
	{
		return GlobeStyle.CLASSIC;
	}

	@ConfigItem(
			keyName = "skillIconMode",
			name = "Skill Icon Mode",
			description = "Controls how skill icons behave.",
			section = globalSection,
			position = 1
	)
	default SkillIconMode skillIconMode() {
		return SkillIconMode.ALPHA_PULSE;
	}

	@ConfigItem(
			keyName = "hideMaxed",
			name = "Hide maxed skills",
			description = "Stop globes from showing up for level 99 skills.",
			section = globalSection,
			position = 2
	)
	default boolean hideMaxed() {
		return false;
	}

	@ConfigItem(
			keyName = "showVirtualLevel",
			name = "Show virtual level",
			description = "Shows virtual level if over 99 in a skill and 'Hide maxed skills' is not checked.",
			section = globalSection,
			position = 3
	)
	default boolean showVirtualLevel() {
		return false;
	}

	@ConfigItem(
			keyName = "disableXpGlobes",
			name = "Disable XP globes",
			description = "Completely disables the XP globes overlay.",
			section = globalSection,
			position = 4
	)
	default boolean disableXpGlobes()
	{
		return false;
	}

	@ConfigItem(
			keyName = "disableLevelUpPopups",
			name = "Disable level up popups",
			description = "Completely disables the level up popup overlay.",
			section = globalSection,
			position = 5
	)
	default boolean disableLevelUpPopups()
	{
		return false;
